// ===== Settings for the KPI DRIVER booking workflows (pasted at the top of each "Validate" node) =====
const LOCATION_ID = 'nLOdLoui5CvpzktszMJx';      // KPI DRIVER sub-account (read from the live HighLevel forms)
const CALENDAR_ID = '17jl7cP7dvOAU48s6C3L';      // the ONE discovery calendar. Default: the current header calendar.
const DURATION_MIN = 45;                          // must match the calendar's slot length
const CONTACT_SOURCE = 'SEO';                     // HighLevel contact "source", as the old forms set it
// Custom fields the website may write (HighLevel custom field ids). Anything else in a request is ignored.
const BOOKING_FIELDS = ['st1eCAFAHDcgPM4VvtNn', 'Z8TSBkLl0c3nkOh0d0bj', 'h4JApkD7A1meEgqfLJ4v', 'zntmhqZEVR510izM1Amv',
  'ARe4MceHNpyuA2cKkIEw', 'qmkmAZyHzfeRFjkRKQaw', 'UWxeByWt7W4EuIVVAQsm', 'J1MTiekQt4vbamz8JFee', 'u6f3OtUsag2gUpFKEHCy',
  'TgvNUU7bOSq4YSB2FS9w', 'xOz64JUSqg9hFWthmar5', 'QfNSOY8w6fJUpyxW9al1', '9aMGEJzyATDb4ZGnPLt7', 'rihpUXcXicHdCxEo4CfX',
  'sqX5fTAKqUuNRwdoxaag', 'uclYhjBFIyedqd8xqYwE', 'VLoxJWATbFZMgMOfBb4P', 'kjvFHgnOa8iVNV7YiiBN', 'LNdrE1FEgFjbPydSCntV',
  'FohJiIh9tGFKXI02LSUD', 'crnTGUSW3StY8VTOqaR2', 'EI2ls6K7uJFe75PmRPaX', 'U26ojrxlzQxC1kwAMvki', 'O5yyMN7TXsWzblxrHUfO'];
// ===== end of settings =====

// Shared helpers (pasted into each Validate node after the settings).
const clean = o => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined && v !== null && v !== ''));
const str = (v, n = 200) => (v == null ? '' : String(v)).trim().slice(0, n);
const isEmail = v => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v);
function phoneE164(v) {
  const raw = str(v, 40); if (!raw) return '';
  const digits = raw.replace(/\D/g, '');
  if (raw.startsWith('+')) return '+' + digits;
  if (digits.length === 10) return '+1' + digits;            // US/Canada without country code
  if (digits.length === 11 && digits[0] === '1') return '+' + digits;
  return raw;                                                // leave anything else for HighLevel to parse
}
function pickFields(list, allowed) {
  const ok = new Set(allowed);
  return (Array.isArray(list) ? list : []).filter(f => f && ok.has(f.id)).map(f => ({
    id: f.id,
    fieldValue: Array.isArray(f.fieldValue) ? f.fieldValue.map(x => str(x, 200)).slice(0, 25)
      : typeof f.fieldValue === 'number' ? f.fieldValue : str(f.fieldValue, 5000)
  }));
}
function clientIp(headers) {
  const h = headers || {};
  return str(h['cf-connecting-ip'] || h['x-forwarded-for'] || h['x-real-ip'] || '', 100).split(',')[0].trim();
}
function contextLines(ctx) {
  ctx = ctx || {};
  const utm = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'gclid', 'fbclid', 'msclkid']
    .filter(k => ctx[k]).map(k => `${k}: ${str(ctx[k], 200)}`);
  return [`Page: ${str(ctx.page_url, 500)}`, `Landing page: ${str(ctx.landing_page, 500)}`,
    `Referrer: ${str(ctx.first_referrer || ctx.referrer, 500) || 'direct'}`, ...utm];
}
const reject = (code, message, status = 400) => [{ json: { ok: false, status, code, message } }];

// Validate the website booking and build every HighLevel request body.
const req = $input.first().json;
const b = req.body || {};
if (b.hp) return [{ json: { ok: false, spam: true, status: 200 } }];                 // honeypot: pretend all is well
if (b.type !== 'booking') return reject('invalid', 'Unexpected form type.');
const c = b.contact || {};
const email = str(c.email, 200).toLowerCase();
if (!str(c.firstName) || !str(c.lastName) || !isEmail(email) || !str(c.phone)) return reject('invalid', 'Please fill in your name, email and phone.');
if (!b.consent || b.consent.sms !== true) return reject('invalid', 'Please tick the SMS consent box.');
const start = Date.parse(b.slot && b.slot.start);
if (!start || start < Date.now() + 5 * 60000) return reject('slot_taken', 'That time is no longer available. Please pick another one.', 409);
const end = start + DURATION_MIN * 60000;
const source = str(b.booking_source, 120) || 'Website';
const tz = str(b.slot.timezone || c.timezone, 60);

const upsert = clean({
  locationId: LOCATION_ID,
  firstName: str(c.firstName, 80), lastName: str(c.lastName, 80), email, phone: phoneE164(c.phone),
  companyName: str(c.companyName, 120), address1: str(c.address1, 200), city: str(c.city, 80), state: str(c.state, 80),
  postalCode: str(c.postalCode, 20), country: str(c.country, 2).toUpperCase(), timezone: tz, source: CONTACT_SOURCE,
  customFields: pickFields(b.customFields, BOOKING_FIELDS),
  dndSettings: { sms: { status: 'inactive', message: 'SMS consent given on the website booking form' } }
});

const appt = {
  calendarId: CALENDAR_ID, locationId: LOCATION_ID,
  startTime: new Date(start).toISOString(), endTime: new Date(end).toISOString(),
  title: `Discovery Call · ${upsert.firstName} ${upsert.lastName}`,
  appointmentStatus: 'confirmed',
  description: `Booked on the website · ${source}`,
  toNotify: true                                   // run the calendar's confirmation/reminder automations
};

const ip = clientIp(req.headers);
const note = [
  `Website booking · ${source}`,
  `Call: ${str(b.slot.display, 120) || appt.startTime} (${tz})`,
  '',
  ...(Array.isArray(b.answers) ? b.answers : []).slice(0, 60).map(a => `${str(a.q, 200)}: ${str(a.a, 2000)}`),
  '',
  `SMS consent: YES · ${str(b.consent.at, 40)} · IP ${ip || 'n/a'} · ${str(b.consent.page, 500)}`,
  `Consent text: ${str(b.consent.text, 1000)}`,
  '',
  ...contextLines(b.context)
].join('\n');

return [{ json: { ok: true, source, upsert, appt, note, tags: ['website booking', `src: ${source}`.toLowerCase()] } }];

// Did HighLevel save the contact? (the HTTP node runs with "full response" + "never error")
const prev = $('Validate').first().json;
const r = $input.first().json;
const id = r.body && r.body.contact && r.body.contact.id;
if (r.statusCode >= 200 && r.statusCode < 300 && id) return [{ json: { ...prev, ok: true, contactId: id } }];
return [{ json: { ok: false, status: 502, code: 'crm_error', message: "We couldn't save your details. Please try again, or email info@kpidriver.com.", detail: r.body } }];

// Did HighLevel book the slot? A taken slot comes back as a 4xx that mentions the slot.
const prev = $('Check contact').first().json;
const r = $input.first().json;
if (r.statusCode >= 200 && r.statusCode < 300 && r.body && r.body.id) {
  return [{ json: { ...prev, ok: true, appointment: { id: r.body.id, startTime: r.body.startTime || prev.appt.startTime } } }];
}
const text = JSON.stringify(r.body || {});
const taken = r.statusCode >= 400 && r.statusCode < 500 && /slot|availab|booked|conflict|not free/i.test(text);
return [{ json: taken
  ? { ok: false, status: 409, code: 'slot_taken', message: 'That time was just taken. Please pick another one.' }
  : { ok: false, status: 502, code: 'crm_error', message: "We couldn't book the call. Please try again, or email info@kpidriver.com.", detail: r.body } }];
